// See lessons/02_control_flow_methods/README.md, "Exercise 1".

namespace CSharpDojo.L02_ControlFlowMethods;

public static class Sequences
{
    /// <summary>
    /// Count down from <paramref name="from"/> to 1 and finish with "liftoff",
    /// comma-separated: Countdown(3) is "3, 2, 1, liftoff".
    /// A start below 1 counts nothing down and is just "liftoff".
    /// </summary>
    public static string Countdown(int from)
    {
        List<string> parts = new List<string>();
        for (int n = from; n >= 1; n--)
        {
            parts.Add(n.ToString());
        }

        parts.Add("liftoff");
        return string.Join(", ", parts);
    }
}

