// 02_control_flow_methods / review1 - a loop plus an out parameter, one more time.
// See lessons/02_control_flow_methods/README.md, "Review".

namespace CSharpDojo.L02_ControlFlowMethods;

public static class Words
{
    /// <summary>
    /// Find the longest space-separated word in <paramref name="sentence"/>,
    /// hand it back through <paramref name="longest"/> and return true.
    /// On a tie the first word wins. A sentence with no words sets
    /// <paramref name="longest"/> to "" and returns false.
    /// </summary>
    public static bool TryLongest(string sentence, out string longest)
    {
        longest = "";
        string[] words = sentence.Split(' ', StringSplitOptions.RemoveEmptyEntries);
        if (words.Length == 0)
        {
            return false;
        }

        foreach (string word in words)
        {
            if (word.Length > longest.Length)
            {
                longest = word;
            }
        }

        return true;
    }
}

