// 09_delegates_events_lambdas / ex1 - Func and Action: behaviour as an argument.
// See lessons/09_delegates_events_lambdas/README.md, "Exercise 1".

namespace CSharpDojo.L09_DelegatesEventsLambdas;

public static class Behaviours
{
    /// <summary>
    /// Every item, put through <paramref name="transform"/>, in order.
    /// The method decides WHEN to call it; the caller decides WHAT it does.
    /// </summary>
    public static List<T> Apply<T>(IEnumerable<T> items, Func<T, T> transform)
    {
        List<T> results = new List<T>();
        foreach (T item in items)
        {
            results.Add(transform(item));
        }

        return results;
    }

    /// <summary>How many items the predicate says yes to.</summary>
    public static int CountWhere<T>(IEnumerable<T> items, Func<T, bool> predicate)
    {
        int count = 0;
        foreach (T item in items)
        {
            if (predicate(item))
            {
                count++;
            }
        }

        return count;
    }

    /// <summary>
    /// Call <paramref name="action"/> once for each number from 1 to
    /// <paramref name="times"/>, in order. An Action returns nothing: it is
    /// called for its effect.
    /// </summary>
    public static void Repeat(int times, Action<int> action)
    {
        for (int i = 1; i <= times; i++)
        {
            action(i);
        }
    }
}

references.Ex2.cs:
// 09_delegates_events_lambdas / ex2 - closures: what a lambda captures, and when.
// See lessons/09_delegates_events_lambdas/README.md, "Exercise 2".

namespace CSharpDojo.L09_DelegatesEventsLambdas;

public static class Closures
{
    /// <summary>
    /// A counter with no class behind it: the returned function hands back
    /// 1, then 2, then 3... The state lives in a local variable that the
    /// lambda captured.
    /// </summary>
    public static Func<int> MakeCounter()
    {
        int count = 0;
        return () => ++count;
    }

    /// <summary>
    /// Build three functions inside a plain `for (int i = 0; i &lt; 3; i++)`
    /// loop, each one `() =&gt; i`. Write it the obvious way and let the gate
    /// tell you what they return - do NOT copy i into a local first.
    /// </summary>
    public static List<Func<int>> FromForLoop()
    {
        List<Func<int>> functions = new List<Func<int>>();
        for (int i = 0; i < 3; i++)
        {
            functions.Add(() => i);
        }

        return functions;
    }

    /// <summary>
    /// The same three functions, built by a `foreach` over new[] { 0, 1, 2 },
    /// each one returning the loop variable.
    /// </summary>
    public static List<Func<int>> FromForeachLoop()
    {
        List<Func<int>> functions = new List<Func<int>>();
        foreach (int i in new[] { 0, 1, 2 })
        {
            functions.Add(() => i);
        }

        return functions;
    }
}

