// d03_control_flow / ex3 - loops that stop early.
// See lessons/d03_control_flow/README.md, "Exercise 3".

namespace CSharpDojo.D03_ControlFlow;

public static class Search
{
    /// <summary>
    /// The index of the FIRST element equal to target, or -1 when there is
    /// none. Stop as soon as you find it.
    /// </summary>
    public static int FirstIndexOf(int[] values, int target)
    {
        for (int i = 0; i < values.Length; i++)
        {
            if (values[i] == target)
            {
                return i;
            }
        }

        return -1;
    }

    /// <summary>
    /// The index of the LAST element equal to target, or -1 when there is none.
    /// </summary>
    public static int LastIndexOf(int[] values, int target)
    {
        for (int i = values.Length - 1; i >= 0; i--)
        {
            if (values[i] == target)
            {
                return i;
            }
        }

        return -1;
    }
}

