// d03_control_flow / ex6 - nested loops.
// See lessons/d03_control_flow/README.md, "Exercise 6".

using System.Text;

namespace CSharpDojo.D03_ControlFlow;

public static class Grid
{
    /// <summary>
    /// A left-aligned triangle of "#": row i has i hashes, rows separated by
    /// "\n", no trailing newline. A height of 0 or less gives "".
    /// </summary>
    public static string Triangle(int height)
    {
        StringBuilder art = new StringBuilder();
        for (int row = 1; row <= height; row++)
        {
            if (row > 1)
            {
                art.Append('\n');
            }

            for (int column = 0; column < row; column++)
            {
                art.Append('#');
            }
        }

        return art.ToString();
    }

    /// <summary>
    /// How many pairs of DIFFERENT positions (i &lt; j) hold values adding up
    /// to target. Equal values at different positions count separately.
    /// </summary>
    public static int CountPairs(int[] values, int target)
    {
        int pairs = 0;
        for (int i = 0; i < values.Length; i++)
        {
            for (int j = i + 1; j < values.Length; j++)
            {
                if (values[i] + values[j] == target)
                {
                    pairs++;
                }
            }
        }

        return pairs;
    }
}

exercises.importantHints:
## Hint 1

Walk the string from the END to the start. That removes the hardest part of
Luhn - "every second digit from the right" is a nuisance to work out from the
left when the length is unknown and separators are scattered through it.

Keep two counters: the running total, and how many *digits* you have seen
(which is not the same as how many characters you have visited).

## Hint 2

```csharp
for (int i = input.Length - 1; i >= 0; i--)
{
    char c = input[i];
    if (c == ' ' || c == '-') continue;
    if (!char.IsAsciiDigit(c)) return false;
    int digit = c - '0';
    if (seen % 2 == 1) { digit *= 2; if (digit > 9) digit -= 9; }
    total += digit;
    seen++;
}
```

`seen % 2 == 1` is the "every second digit" test, and it works because `seen`
counts digits rather than characters - so separators cannot shift the parity.

`c - '0'` converts a digit character to its value: `char` arithmetic promotes
to `int`, and the digits are contiguous in the character set.

Left to you: `digit -= 9` versus summing the two decimal digits of the doubled
value. They are the same for every input in range - be able to explain why.

references.Ex7.cs:
// d03_control_flow / ex7 - the Luhn check digit.
// See lessons/d03_control_flow/README.md, "Exercise 7".

namespace CSharpDojo.D03_ControlFlow;

public static class Checksum
{
    /// <summary>
    /// Does this string pass the Luhn check?
    ///
    /// Spaces and hyphens are ignored. Any other non-digit makes it invalid,
    /// and so does having fewer than two digits. Otherwise: walking from the
    /// RIGHTMOST digit leftwards, double every second digit (the 2nd, 4th, ...
    /// from the right); a doubled value above 9 has 9 subtracted. The number is
    /// valid when the total of all the digits divides by 10.
    /// </summary>
    public static bool IsValidLuhn(string input)
    {
        int total = 0;
        int seen = 0;

        for (int i = input.Length - 1; i >= 0; i--)
        {
            char c = input[i];
            if (c == ' ' || c == '-')
            {
                continue;
            }

            if (!char.IsAsciiDigit(c))
            {
                return false;
            }

            int digit = c - '0';
            if (seen % 2 == 1)
            {
                digit *= 2;
                if (digit > 9)
                {
                    digit -= 9;
                }
            }

            total += digit;
            seen++;
        }

        return seen >= 2 && total % 10 == 0;
    }
}

