                + "README ex7.");
        Teach.Throws<ArgumentOutOfRangeException>(() => Money.Split(10m, -2), "Nor a negative count.");
        Teach.Throws<ArgumentOutOfRangeException>(() => Money.Split(-1m, 2),
            "And a negative total is out of range too.");
