        Teach.Equal("2", Args.ValueOr(Args.Parse("--x=1", "--x=2"), "x"),
            "A repeated option keeps the last value, which is what every shell tool does.");
        Teach.Equal("", Args.ValueOr(Args.Parse("--k="), "k", "MISSING"),
