        Teach.Equal(4, bigger.Guests, "The copy has the new count...");
        Teach.Equal("Ada", bigger.Name, "...the same name...");
        Teach.Equal("window", bigger.Note ?? "", "...and the same note.");
        Teach.Equal(2, noted.Guests,
