// d11_equality_semantics / ex6 - a comparer for someone else's type.
// See lessons/d11_equality_semantics/README.md, "Exercise 6".

namespace CSharpDojo.D11_EqualitySemantics;

/// <summary>Not ours to change - so a different notion of "same" lives outside it.</summary>
public class Reading
{
    public Reading(double latitude, double longitude)
    {
        Latitude = latitude;
        Longitude = longitude;
    }

    public double Latitude { get; }

    public double Longitude { get; }
}

/// <summary>
/// Two readings are the same when both coordinates FLOOR to the same whole
/// number - that is, when they fall in the same one-degree grid square.
/// </summary>
public class GridCellComparer : IEqualityComparer<Reading>
{
    /// <summary>Two nulls are equal; one null is not; otherwise compare cells.</summary>
    public bool Equals(Reading? x, Reading? y)
    {
        if (x is null || y is null)
        {
            return x is null && y is null;
        }

        return Cell(x) == Cell(y);
    }

    /// <summary>A hash of the cell, so equal readings hash the same.</summary>
    public int GetHashCode(Reading obj)
    {
        (int latitude, int longitude) = Cell(obj);
        return HashCode.Combine(latitude, longitude);
    }

    private static (int Latitude, int Longitude) Cell(Reading reading) =>
        ((int)Math.Floor(reading.Latitude), (int)Math.Floor(reading.Longitude));
}

public static class Readings
{
    /// <summary>How many distinct grid cells the readings fall in.</summary>
    public static int DistinctCells(IEnumerable<Reading> readings) =>
        readings.Distinct(new GridCellComparer()).Count();
}

exercises.importantHints:
## Hint 1

This is the full contract, written out once so you never have to guess again.
Five members, and each has a job:

- `Equals(Money?)` - the real comparison, from `IEquatable<T>`;
- `Equals(object?)` - delegates to it after a type test;
- `GetHashCode()` - built from the same fields;
- `operator ==` - handles nulls, then delegates;
- `operator !=` - `!(left == right)`.

## Hint 2

The operators are where the care goes, because they must not recurse:

```csharp
public static bool operator ==(Money? left, Money? right)
{
    if (left is null) return right is null;
    return left.Equals(right);
}
```

`left is null` rather than `left == null` - the second would call this operator
again and stack-overflow. The `is null` pattern is not sugar here; it is the
only safe test.

`Equals(Money? other)` needs `other is not null` and then the field comparison.
Compare `Currency` with `StringComparison.OrdinalIgnoreCase` and hash it the
same way - `HashCode.Combine(Amount, StringComparer.OrdinalIgnoreCase.GetHashCode(Currency))`.

The class is `sealed`, which is deliberate: it removes the inheritance question
ex8 is about, and it is what lets `Equals` use a simple type test with a clear
conscience.

references.Ex7.cs:
// d11_equality_semantics / ex7 - the whole contract, by hand.
// See lessons/d11_equality_semantics/README.md, "Exercise 7".

namespace CSharpDojo.D11_EqualitySemantics;

/// <summary>Sealed on purpose: it removes the inheritance question entirely.</summary>
public sealed class Money : IEquatable<Money>
{
    public Money(decimal amount, string currency)
    {
        Amount = amount;
        Currency = currency;
    }

    public decimal Amount { get; }

    public string Currency { get; }

    /// <summary>
    /// The real comparison: same amount, and same currency ignoring case.
    /// null is never equal to an instance.
    /// </summary>
    public bool Equals(Money? other)
    {
        if (other is null)
        {
            return false;
        }

        return Amount == other.Amount
            && string.Equals(Currency, other.Currency, StringComparison.OrdinalIgnoreCase);
    }

    /// <summary>Delegates to the typed version after a type test.</summary>
    public override bool Equals(object? obj) => obj is Money other && Equals(other);

    /// <summary>Built from the same two values, with the same case rule.</summary>
    public override int GetHashCode() =>
        HashCode.Combine(Amount, StringComparer.OrdinalIgnoreCase.GetHashCode(Currency));

    /// <summary>
    /// Handles nulls on either side and then delegates. Test for null with
    /// `is null` - `== null` in here would call this operator again.
    /// </summary>
    public static bool operator ==(Money? left, Money? right)
    {
        if (left is null)
        {
            return right is null;
        }

        return left.Equals(right);
    }

    /// <summary>The opposite of ==.</summary>
    public static bool operator !=(Money? left, Money? right) => !(left == right);
}

