// d14_sets_queues_stacks / ex3 - a queue: taking, peeking, and postponing.
// See lessons/d14_sets_queues_stacks/README.md, "Exercise 3".

namespace CSharpDojo.D14_SetsQueuesStacks;

public static class Tickets
{
    /// <summary>Removes and returns the front ticket, or null when the queue is empty.</summary>
    public static string? TakeNext(Queue<string> queue)
    {
        return queue.TryDequeue(out string? ticket) ? ticket : null;
    }

    /// <summary>
    /// Moves the front ticket to the BACK of the queue and returns it, or
    /// returns null (touching nothing) when the queue is empty.
    /// </summary>
    public static string? Postpone(Queue<string> queue)
    {
        if (!queue.TryDequeue(out string? ticket))
        {
            return null;
        }

        queue.Enqueue(ticket);
        return ticket;
    }

    /// <summary>
    /// The next <paramref name="count"/> tickets in service order WITHOUT
    /// removing any of them; fewer when the queue is shorter.
    /// </summary>
    public static List<string> UpNext(Queue<string> queue, int count)
    {
        return queue.Take(count).ToList();
    }
}

exercises.importantHints:
## Hint 1

Keep a `Stack<string>` of snapshots. The one decision that matters: `Type`
pushes the text AS IT WAS, before appending. If you push after, Undo
"restores" the state you are already looking at - the gate's first Undo
assertion is written to catch exactly that.

## Hint 2

```csharp
public void Type(string addition)
{
    _history.Push(Text);
    Text += addition;
}
```

`Undo` checks `_history.Count` first - return false on empty rather than
letting `Pop` throw - and `CanUndo` is that same count as a bool.

references.Ex4.cs:
// d14_sets_queues_stacks / ex4 - an undo stack.
// See lessons/d14_sets_queues_stacks/README.md, "Exercise 4".

namespace CSharpDojo.D14_SetsQueuesStacks;

public class Draft
{
    private readonly Stack<string> _history = new Stack<string>();

    /// <summary>The current text. Starts empty.</summary>
    public string Text { get; private set; } = "";

    /// <summary>Whether there is anything to undo.</summary>
    public bool CanUndo
    {
        get { return _history.Count > 0; }
    }

    /// <summary>Appends to the text, remembering the previous text for Undo.</summary>
    public void Type(string addition)
    {
        _history.Push(Text);
        Text += addition;
    }

    /// <summary>
    /// Restores the text as it was before the most recent Type. Returns false
    /// (changing nothing) when there is nothing left to undo.
    /// </summary>
    public bool Undo()
    {
        if (_history.Count == 0)
        {
            return false;
        }

        Text = _history.Pop();
        return true;
    }
}

