// d15_iterators_yield / ex1 - two straightforward iterators.
// See lessons/d15_iterators_yield/README.md, "Exercise 1".

namespace CSharpDojo.D15_IteratorsYield;

public static class Ranges
{
    /// <summary>
    /// Yields first, first+1, ... last (inclusive). When last is below first,
    /// yields nothing at all.
    /// </summary>
    public static IEnumerable<int> UpTo(int first, int last)
    {
        for (int value = first; value <= last; value++)
        {
            yield return value;
        }
    }

    /// <summary>
    /// Yields <paramref name="item"/> exactly <paramref name="times"/> times;
    /// zero (or fewer) times yields nothing.
    /// </summary>
    public static IEnumerable<string> Repeat(string item, int times)
    {
        for (int i = 0; i < times; i++)
        {
            yield return item;
        }
    }
}

exercises.importantHints:
## Hint 1

`Stutter` is one `foreach` containing TWO `yield return item;` statements in
a row. Do not collect into a list - the gate counts how many items were read
from the source, and a list reads all of them immediately.

## Hint 2

`Numbered` keeps a counter local:

```csharp
int number = 1;
foreach (string item in items)
{
    yield return $"{number}. {item}";
    number++;
}
```

Iterator locals live inside the compiled state machine, so `number` keeps
its value between pulls - that is why this just works.

