// d16_delegates_lambdas / ex5 - building comparisons out of comparisons.
// See lessons/d16_delegates_lambdas/README.md, "Exercise 5".

namespace CSharpDojo.D16_DelegatesLambdas;

public static class Comparers
{
    /// <summary>
    /// A Comparison that orders by an int key, ascending: the key function is
    /// applied to both operands and the keys compared.
    /// </summary>
    public static Comparison<T> ByKey<T>(Func<T, int> key)
    {
        return (a, b) => key(a).CompareTo(key(b));
    }

    /// <summary>The same ordering, upside down.</summary>
    public static Comparison<T> Reversed<T>(Comparison<T> inner)
    {
        return (a, b) => inner(b, a);
    }

    /// <summary>
    /// Orders by <paramref name="first"/>, letting <paramref name="second"/>
    /// break the ties (when first answers 0).
    /// </summary>
    public static Comparison<T> Then<T>(Comparison<T> first, Comparison<T> second)
    {
        return (a, b) =>
        {
            int result = first(a, b);
            return result != 0 ? result : second(a, b);
        };
    }
}

exercises.importantHints:
## Hint 1

One local variable, two lambdas, both mentioning it. That is the whole design.
The moment two lambdas use the same local, the compiler puts that local on a
single hidden object and gives both delegates a reference to it - so a write
through one is visible through the other.

Do not copy the balance into anything.

## Hint 2

```csharp
public static (Action<int> Deposit, Func<int> Balance) MakeAccount(int opening)
{
    int balance = opening;

    Action<int> deposit = amount => { /* guard, then balance += amount; */ };
    Func<int> read = () => balance;

    return (deposit, read);
}
```

The guard belongs *inside* the deposit lambda, because the lambda is the only
way anyone can reach `balance` - and it has to throw before the `+=`, so a
refused deposit leaves no trace.

Each call to `MakeAccount` runs the `int balance = opening;` line again, which
is what makes two accounts independent. If you find yourself reaching for a
static field to hold the balance, you have written a class the hard way.

references.Ex6.cs:
// d16_delegates_lambdas / ex6 - two lambdas sharing one captured variable.
// See lessons/d16_delegates_lambdas/README.md, "Exercise 6".

namespace CSharpDojo.D16_DelegatesLambdas;

public static class Accounts
{
    /// <summary>
    /// A tiny account with no class: returns a Deposit action and a Balance
    /// query that CLOSE OVER THE SAME local variable, so what one writes the
    /// other reads. Each call to MakeAccount creates a fresh, independent
    /// balance. A negative deposit throws ArgumentOutOfRangeException.
    /// </summary>
    public static (Action<int> Deposit, Func<int> Balance) MakeAccount(int opening)
    {
        int balance = opening;

        Action<int> deposit = amount =>
        {
            if (amount < 0)
            {
                throw new ArgumentOutOfRangeException(nameof(amount), amount, "deposits cannot be negative");
            }

            balance += amount;
        };

        Func<int> read = () => balance;

        return (deposit, read);
    }
}

