// d22_exceptions / ex4 - rethrowing without destroying the evidence.
// See lessons/d22_exceptions/README.md, "Exercise 4".

namespace CSharpDojo.D22_Exceptions;

public static class Rethrow
{
    /// <summary>
    /// Written for you, and deliberately wrong: `throw ex;` starts the stack
    /// trace again from this line, so wherever the exception really came from
    /// is gone.
    /// </summary>
    public static void Losing(Action action, List<string> log)
    {
        try
        {
            action();
        }
        catch (Exception ex)
        {
            log.Add($"seen:{ex.Message}");
            throw ex;
        }
    }

    /// <summary>
    /// The same logging, but the original stack trace survives.
    /// </summary>
    public static void Keeping(Action action, List<string> log)
    {
        try
        {
            action();
        }
        catch (Exception ex)
        {
            log.Add($"seen:{ex.Message}");
            throw;
        }
    }

    /// <summary>
    /// Catches anything and throws an InvalidOperationException with the
    /// message "wrapped" and the original exception as its InnerException.
    /// </summary>
    public static void Wrapping(Action action)
    {
        try
        {
            action();
        }
        catch (Exception ex)
        {
            throw new InvalidOperationException("wrapped", ex);
        }
    }
}

exercises.importantHints:
## Hint 1

`Probe` is written for you and already logs its own open and dispose. Your job
is to make sure the dispose happens - which is what `using` is for.

`Use` also has to catch, because it returns `"failed:..."` rather than
throwing. Think about where the `catch` goes relative to the `using`.

## Hint 2

```csharp
using (Probe probe = new Probe(name, log))
{
    try { body(probe); return "ok"; }
    catch (Exception ex) { return $"failed:{ex.Message}"; }
}
```

The `using` compiles into a `try`/`finally`, so the dispose happens on the way
out of either `return`.

`UseTwo` stacks two of them and catches nothing:

```csharp
using (new Probe("outer", log))
using (new Probe("inner", log))
{
    body();
}
```

Predict the disposal order before you run the test. Nested usings unwind in
reverse - last opened, first closed - and that is not arbitrary: the inner
resource may need the outer one to still be alive while it shuts down.

references.Ex5.cs:
// d22_exceptions / ex5 - cleanup that happens anyway.
// See lessons/d22_exceptions/README.md, "Exercise 5".

namespace CSharpDojo.D22_Exceptions;

// The gate builds these. Written for you.
public sealed class Probe : IDisposable
{
    private readonly List<string> _log;

    public Probe(string name, List<string> log)
    {
        Name = name;
        _log = log;
        _log.Add($"open:{name}");
    }

    public string Name { get; }

    public bool Disposed { get; private set; }

    public void Dispose()
    {
        if (Disposed)
        {
            return;
        }

        Disposed = true;
        _log.Add($"dispose:{Name}");
    }
}

public static class Resources
{
    /// <summary>
    /// Opens a Probe with that name, runs the body on it, and disposes it
    /// whatever happens. Returns "ok", or "failed:&lt;message&gt;" when the
    /// body threw - and the probe is disposed before either value is returned.
    /// </summary>
    public static string Use(string name, List<string> log, Action<Probe> body)
    {
        using (Probe probe = new Probe(name, log))
        {
            try
            {
                body(probe);
                return "ok";
            }
            catch (Exception ex)
            {
                return $"failed:{ex.Message}";
            }
        }
    }

    /// <summary>
    /// Opens "outer" and then "inner", runs the body, and disposes both -
    /// inner first, because it was opened last. Any exception from the body
    /// escapes, after the disposals.
    /// </summary>
    public static void UseTwo(List<string> log, Action body)
    {
        using (new Probe("outer", log))
        using (new Probe("inner", log))
        {
            body();
        }
    }
}

