// i2_interview_drills / ex3 - word frequency. Time-box: 15 minutes.
// See lessons/i2_interview_drills/README.md, "Exercise 3".

using System.Text.RegularExpressions;

namespace CSharpDojo.I2_InterviewDrills;

public static class WordFrequency
{
    /// <summary>
    /// The <paramref name="count"/> most common words as "word: n", most
    /// frequent first and ties broken alphabetically. Words are case-insensitive
    /// and are separated by anything that is not a letter, so "Don't" is two
    /// words and punctuation never ends up inside one.
    /// </summary>
    public static List<string> Top(string text, int count)
    {
        return Regex.Matches(text, "[a-zA-Z]+")
            .Select(match => match.Value.ToLowerInvariant())
            .GroupBy(word => word)
            .OrderByDescending(group => group.Count())
            .ThenBy(group => group.Key)
            .Take(count)
            .Select(group => $"{group.Key}: {group.Count()}")
            .ToList();
    }
}

